CREATE TABLE IF NOT EXISTS users ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT UNIQUE, phone TEXT UNIQUE, pass_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student' CHECK (role IN ('student','admin')), active INTEGER NOT NULL DEFAULT 1, must_change INTEGER NOT NULL DEFAULT 1, notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), last_login TEXT ); CREATE TABLE IF NOT EXISTS sessions ( token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, user_agent TEXT ); CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id); CREATE TABLE IF NOT EXISTS courses ( id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, subtitle TEXT, intro TEXT, audience TEXT, status TEXT NOT NULL DEFAULT 'soon' CHECK (status IN ('open','soon','hidden')), sort INTEGER NOT NULL DEFAULT 0 ); CREATE TABLE IF NOT EXISTS plans ( id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, code TEXT NOT NULL CHECK (code IN ('basic','pro')), name TEXT NOT NULL, features TEXT, price REAL NOT NULL DEFAULT 0, show_price INTEGER NOT NULL DEFAULT 0, discount_type TEXT NOT NULL DEFAULT 'none' CHECK (discount_type IN ('none','percent','amount')), discount_value REAL NOT NULL DEFAULT 0, discount_ends TEXT, visible INTEGER NOT NULL DEFAULT 1, UNIQUE (course_id, code) ); CREATE TABLE IF NOT EXISTS levels ( id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, num INTEGER NOT NULL, title TEXT NOT NULL, topics TEXT, teaser TEXT, UNIQUE (course_id, num) ); CREATE TABLE IF NOT EXISTS materials ( id INTEGER PRIMARY KEY AUTOINCREMENT, level_id INTEGER NOT NULL REFERENCES levels(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('pdf','video')), title TEXT NOT NULL, min_plan TEXT NOT NULL DEFAULT 'basic' CHECK (min_plan IN ('basic','pro')), pages INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, video_url TEXT, sort INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE TABLE IF NOT EXISTS enrollments ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, plan_code TEXT NOT NULL DEFAULT 'basic' CHECK (plan_code IN ('basic','pro')), starts_at TEXT NOT NULL DEFAULT (date('now')), expires_at TEXT, UNIQUE (user_id, course_id) ); CREATE TABLE IF NOT EXISTS progress ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, material_id INTEGER NOT NULL REFERENCES materials(id) ON DELETE CASCADE, done_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY (user_id, material_id) ); CREATE TABLE IF NOT EXISTS exams ( id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('level','cumulative')), after_level INTEGER NOT NULL, title TEXT NOT NULL, question_count INTEGER NOT NULL DEFAULT 10, pass_pct REAL NOT NULL DEFAULT 50, UNIQUE (course_id, kind, after_level) ); CREATE TABLE IF NOT EXISTS questions ( id INTEGER PRIMARY KEY AUTOINCREMENT, exam_id INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE, body TEXT NOT NULL, options TEXT NOT NULL, answer INTEGER NOT NULL, explanation TEXT ); CREATE INDEX IF NOT EXISTS idx_questions_exam ON questions(exam_id); CREATE TABLE IF NOT EXISTS attempts ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, exam_id INTEGER NOT NULL REFERENCES exams(id) ON DELETE CASCADE, question_ids TEXT NOT NULL, score REAL, passed INTEGER, started_at TEXT NOT NULL DEFAULT (datetime('now')), submitted_at TEXT ); CREATE INDEX IF NOT EXISTS idx_attempts_user ON attempts(user_id, exam_id); CREATE TABLE IF NOT EXISTS certificates ( code TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE, issued_at TEXT NOT NULL DEFAULT (date('now')), UNIQUE (user_id, course_id) ); CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT ); CREATE TABLE IF NOT EXISTS files ( key TEXT PRIMARY KEY, type TEXT NOT NULL, data BLOB NOT NULL ); INSERT OR IGNORE INTO settings (key, value) VALUES ('whatsapp', '201500069190'); INSERT OR IGNORE INTO settings (key, value) VALUES ('whatsapp_display', '01500069190'); INSERT OR IGNORE INTO settings (key, value) VALUES ('lecturer_whatsapp', '201500069190'); INSERT OR IGNORE INTO settings (key, value) VALUES ('brand_name', 'Mr. Islam Khalifa | Accounting'); INSERT OR IGNORE INTO settings (key, value) VALUES ('footer_line1', 'Mr. Islam Khalifa | Accounting'); INSERT OR IGNORE INTO settings (key, value) VALUES ('footer_line2', 'اتعلم .. طبق .. ابن'); INSERT OR IGNORE INTO settings (key, value) VALUES ('subscribe_message', 'السلام عليكم، عايز أشترك في كورس: {course} ({plan})'); INSERT OR IGNORE INTO settings (key, value) VALUES ('follow_message', 'السلام عليكم يا مستر إسلام، أنا {name} من متدربي كورس {course}، واقف عند {level} ومحتاج أسأل عن:'); INSERT OR IGNORE INTO settings (key, value) VALUES ('notify_message', 'السلام عليكم، بلغني أول ما كورس {course} يفتح.'); INSERT OR IGNORE INTO settings (key, value) VALUES ('cert_signature', 'Islam Khalifa'); INSERT OR IGNORE INTO settings (key, value) VALUES ('cert_bg', ''); INSERT OR IGNORE INTO courses (slug, title, subtitle, intro, audience, status, sort) VALUES ('financial', 'المحاسبة المالية', 'من الصفر لحد القوائم المالية، مع قصة شركة الكريم', 'كريم كان عنده حلم بسيط: شركة صغيرة لتجارة الأجهزة الكهربائية والإلكترونيات. معاه رأس مال محدود، وخبرة في السوق، ومفيش ولا دفتر. في الكورس ده هتمشي جنبه خطوة بخطوة، من أول جنيه دخل "شركة الكريم للتجارة والتوزيع" لحد ما بقى عندها قوائم مالية تتقرا قدام البنك والشريك. كل مستوى فصل من القصة، وكل مشكلة بتقابل كريم درس محاسبي هتطبقه بإيدك وتفهم المنطق اللي وراه.', 'المحاسبين حديثي التخرج والـ Junior، وأصحاب الشركات والبيزنس الناشئ', 'open', 1); INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'basic', 'الباقة الأساسية', '["المادة العلمية PDF لكل المستويات", "امتحانات المستويات والتراكمي", "متابعة مع المحاضر على واتساب", "شهادة إتمام"]', 0, 0, 1 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'pro', 'باقة Pro', '["كل مميزات الباقة الأساسية", "فيديوهات شرح لكل مستوى"]', 0, 0, 0 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO courses (slug, title, subtitle, intro, audience, status, sort) VALUES ('contracting', 'محاسبة المقاولات', 'عقود الإنشاء، المستخلصات، وتكاليف المشروعات', NULL, NULL, 'soon', 2); INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'basic', 'الباقة الأساسية', '["المادة العلمية PDF لكل المستويات", "امتحانات المستويات والتراكمي", "متابعة مع المحاضر على واتساب", "شهادة إتمام"]', 0, 0, 1 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'pro', 'باقة Pro', '["كل مميزات الباقة الأساسية", "فيديوهات شرح لكل مستوى"]', 0, 0, 0 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO courses (slug, title, subtitle, intro, audience, status, sort) VALUES ('ifrs', 'المعايير الدولية IFRS', 'منطق المعايير وتطبيقها العملي في السوق', NULL, NULL, 'soon', 3); INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'basic', 'الباقة الأساسية', '["المادة العلمية PDF لكل المستويات", "امتحانات المستويات والتراكمي", "متابعة مع المحاضر على واتساب", "شهادة إتمام"]', 0, 0, 1 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'pro', 'باقة Pro', '["كل مميزات الباقة الأساسية", "فيديوهات شرح لكل مستوى"]', 0, 0, 0 FROM courses WHERE slug = 'ifrs'; INSERT OR IGNORE INTO courses (slug, title, subtitle, intro, audience, status, sort) VALUES ('tax', 'محاسبة الضرايب', 'القيمة المضافة، الخصم تحت حساب الضريبة، وضريبة الدخل', NULL, NULL, 'soon', 4); INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'basic', 'الباقة الأساسية', '["المادة العلمية PDF لكل المستويات", "امتحانات المستويات والتراكمي", "متابعة مع المحاضر على واتساب", "شهادة إتمام"]', 0, 0, 1 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'pro', 'باقة Pro', '["كل مميزات الباقة الأساسية", "فيديوهات شرح لكل مستوى"]', 0, 0, 0 FROM courses WHERE slug = 'tax'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 1, 'البداية: كريم بيفتح الشركة', 'التأسيس، الفروض والمبادئ المحاسبية، معادلة الميزانية، وطبيعة الحسابات ورأس المال.', 'كريم حط فلوسه وفتح الشركة. أول سؤال هيقابله: الفلوس دي بتاعته ولا بتاعة الشركة؟ هنا هنعرف ليه الشركة شخصية مستقلة، وإزاي معادلة الميزانية بتفضل متزنة في كل لحظة.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 1, 'امتحان المستوى 1', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 2, 'كل عملية ليها وشين', 'نظرية القيد المزدوج، الدورة المستندية، والتسجيل في دفتر اليومية.', 'أول شحنة تلاجات وصلت، ومعاها فاتورة وإذن استلام وإيصال دفع. يسجل إيه وفين؟ هنعرف إن كل عملية ليها طرف مدين وطرف دائن، وإن المستند هو اللي بيحمي المحاسب قبل أي حاجة.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 2, 'امتحان المستوى 2', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 3, 'الأرقام بتتكلم', 'الترحيل إلى دفتر الأستاذ العام والترصيد، وإعداد ميزان المراجعة.', 'بعد شهر اليومية اتملت قيود، وكريم عايز يعرف: معايا كام في الخزينة؟ وعليا كام للموردين؟ هنرحل ونرصد ونطلع ميزان المراجعة، أول تقرير يقول لكريم حساباتك موزونة ولا فيه غلطة.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 3, 'امتحان المستوى 3', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 4, 'على مكتب المشتريات', 'دورة المشتريات ومصروفات النقل، والمردودات والمسموحات، والخصومات بأنواعها.', 'مورد بعت شحنة فيها تالف، وتاني عرض خصم لو الدفع خلال 10 أيام، والنقل ليه فاتورة. هنعرف أثر كل ده على تكلفة البضاعة، والفرق بين الخصم التجاري وخصم تعجيل الدفع.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 4, 'امتحان المستوى 4', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 5, 'العميل دايماً على حق.. بس بحساب', 'دورة المبيعات والعملاء، ومردوداتها ومسموحاتها والخصم المسموح به ومصروفات البيع.', 'المبيعات كبرت: كاش وآجل، وعميل رجع غسالة فيها عيب، وتاني طالب خصم. هنسجل دورة المبيعات كاملة، ونعرف مصروفات البيع بتروح فين.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 5, 'امتحان المستوى 5', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 6, 'المخزن: أغلى أصل عند كريم', 'أنظمة المخزون السلعي (الدوري والمستمر) وطرق تسعير المخزون.', 'كريم اشترى نفس موديل التلفزيون بـ 3 أسعار مختلفة. يبقى تكلفة اللي اتباع كام؟ هنقارن الجرد الدوري والمستمر وطرق التسعير، ونشوف أثر كل طريقة على الربح بمنطق IAS 2.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 6, 'امتحان المستوى 6', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 7, 'عربية التوزيع والمعرض الجديد', 'المحاسبة عن الأصول الثابتة الملموسة وغير الملموسة، وطرق إهلاكها، والاستغناء عنها.', 'كريم اشترى عربية توزيع وجهز معرض واشترى برنامج محاسبي. دي مصروفات ولا أصول؟ هنحسب الإهلاك بطرقه، ونعرف نعمل إيه لما نبيع أصل، بمنطق IAS 16 و IAS 38.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 7, 'امتحان المستوى 7', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 8, 'آخر السنة: ساعة الحقيقة', 'التسويات الجردية الشاملة (المقدمات، المستحقات، والمهمات والأدوات).', 'إيجار مدفوع مقدم لسنة، ومرتبات شهر لسه ما اتصرفتش، وأدوات نصها اتستهلك. هنعمل التسويات علشان الربح يبقى حقيقي مش مجرد رقم في الخزينة.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 8, 'امتحان المستوى 8', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 9, 'كريم كسبان ولا خسران؟', 'قيود الإقفال الختامية وإعداد القوائم المالية الكاملة.', 'اللحظة اللي كريم مستنيها: نقفل الحسابات ونطلع القوائم المالية. هنا هيعرف الفرق بين الكاش والربح، وإزاي يقرا شركته زي ما البنك بيقراها.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 9, 'امتحان المستوى 9', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 10, 'المحاسب اللي بيحمي الشركة', 'الرقابة والعمليات المتقدمة (مذكرة تسوية البنك، المصروفات النثرية، الأوراق التجارية، وتصحيح الأخطاء الدفترية).', 'كشف البنك مش مطابق، والعهدة النثرية محتاجة ضبط، وكمبيالات العملاء قربت تستحق، وقيد قديم طلع غلط. هنا هتمسك أدوات الرقابة اللي بتفرق المحاسب العادي عن اللي الإدارة بتعتمد عليه.' FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 10, 'امتحان المستوى 10', 10, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'cumulative', 3, 'الامتحان التراكمي الأول (المستويات 1 إلى 3)', 20, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'cumulative', 6, 'الامتحان التراكمي الثاني (المستويات 1 إلى 6)', 20, 50 FROM courses WHERE slug = 'financial'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'cumulative', 10, 'الامتحان الشامل (المستويات 1 إلى 10)', 20, 50 FROM courses WHERE slug = 'financial'; ALTER TABLE exams ADD COLUMN duration_min INTEGER NOT NULL DEFAULT 15; ALTER TABLE users ADD COLUMN last_seen TEXT; CREATE TABLE IF NOT EXISTS reading ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, material_id INTEGER NOT NULL REFERENCES materials(id) ON DELETE CASCADE, page INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY (user_id, material_id) ); UPDATE exams SET duration_min = 40 WHERE kind = 'cumulative'; INSERT OR IGNORE INTO settings (key, value) VALUES ('support_whatsapp', '201500069190'); INSERT OR IGNORE INTO settings (key, value) VALUES ('support_message', 'السلام عليكم، أنا {name} من متدربي المنصة، ومحتاج مساعدة فنية في:'); INSERT OR IGNORE INTO settings (key, value) VALUES ('reminder_message', 'أهلاً يا {name}، وحشتنا في كورس {course}! إنت واقف عند {level}. كمل من هنا: {link}'); INSERT OR IGNORE INTO settings (key, value) VALUES ('inactive_days', '7'); UPDATE courses SET subtitle = 'من رأس المال لحد تسليم المفتاح، مع قصة شركة الوعد للمقاولات', intro = 'عاصم مهندس مدني شبع شغل عند الناس، وعماد محاسب قانوني عارف مصايد السوق شبر شبر. اتفقوا على قهوة في مدينة نصر يفتحوا "شركة الوعد للمقاولات" برأس مال 10 مليون جنيه. في الكورس ده هتمشي معاهم من أول جنيه دخل البنك، لمناقصة برج "زهرة النرجس" في التجمع الخامس، لخطابات الضمان والدفعة المقدمة، لحديد الموقع ومستخلصات مقاولي الباطن، لحد التسليم النهائي والميزانية الختامية. كل الأرقام متصلة من أول مستوى لآخر مستوى، وكل مطب في الموقع ليه قيد ومستند ومعيار، على أحدث قوانين الضرايب في مصر.', audience = 'المحاسبين حديثي التخرج والـ Junior، ومحاسبي المواقع، وأي حد عايز يشتغل في شركات المقاولات' WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 1, 'البداية وتأسيس الكيان', 'تأسيس الشركة وجاري الشركاء، مصاريف التأسيس (معيار 23)، تكلفة الأصول الثابتة وسياسة الإهلاك (معيار 10)، وضريبة القيمة المضافة على المعدات بعد القانون 157 لسنة 2025.', 'عاصم عايز ينزل يشتري معدات ويدخل مناقصات بكرة الصبح، وعماد بيقوله: "الـ 10 مليون دول يتبخروا في ست شهور". هنعرف إيه اللي يتحط أصل وإيه اللي يتحمل مصروف، وليه الـ 14% اللي على فاتورة اللودر مش تكلفة.' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 1, 'امتحان المستوى 1', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 2, 'كراسة الشروط ودخول المناقصات', 'مناقصة برج زهرة النرجس، معالجة تكلفة الكراسة طبقاً لمعيار 48، خطاب الضمان الابتدائي والغطاء النقدي المقيد، والحسابات النظامية خارج الميزانية.', 'إعلان في الجريدة عن برج بـ 50 مليون في التجمع الخامس. الكراسة بفلوس، والبنك عايز يحجز جزء من الرصيد قبل ما يطلع خطاب الضمان. يا ترى الفلوس المحجوزة دي لسه بتاعتنا؟' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 2, 'امتحان المستوى 2', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 3, 'الفوز بالمشروع والبدء الفعلي', 'الترسية بـ 48 مليون، خطاب ضمان حسن التنفيذ، الدفعة المقدمة 10% كالتزام مش إيراد، وفتح مركز التكلفة 101 وأكواده الثلاثية (المشروع، المرحلة، بند المقايسة).', 'الشركة كسبت المناقصة، وشيك الدفعة المقدمة دخل البنك. عاصم فاكر إن الشركة بقت غنية، وعماد بيقوله إن الفلوس دي دين علينا لحد ما نشتغلها.' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 3, 'امتحان المستوى 3', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 4, 'المعركة في الموقع', 'مخزون وتشوينات الموقع وأذون الإضافة والصرف، الأجور ومصاريف الموقع، مستخلص مقاول الباطن واستقطاعاته (ضمان أعمال، خصم 1% نموذج 41، تأمينات)، وضريبة القيمة المضافة على مشتريات الموقع ومقاولي الباطن.', 'الحديد وصل والأسمنت اتشوّن، والمعلم حامد داخل المكتب عايز مستخلصه كامل. هنعرف إزاي الخامة ماتبقاش تكلفة إلا بإذن صرف، وإزاي نفك استقطاعات مستخلص الباطن جنيه جنيه.' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 4, 'امتحان المستوى 4', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 5, 'المستخلصات والإيرادات', 'المستخلص الجاري الأول، الاعتراف بالإيراد على مدار الوقت (معيار 48)، ضريبة القيمة المضافة 14% وخصم المدخلات، استرداد الدفعة المقدمة، احتجاز ضمان الأعمال، والخصم تحت حساب الضريبة.', 'الاستشاري اعتمد أول مستخلص. بس الشيك اللي وصل أقل بكتير من قيمة الأعمال. هنعرف كل جنيه اتخصم راح فين، وإمتى الشركة تعترف بالإيراد.' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 5, 'امتحان المستوى 5', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 6, 'الحسابات الختامية وتسليم المفتاح', 'إنجاز 100%، التسليم الابتدائي واسترداد ضمان الأعمال، التسليم النهائي وفك الضمانات، الإهلاك كتكلفة مشروع، ضريبة الدخل 22.5%، وإعداد قائمة الدخل والمركز المالي.', 'البرج اتسلم والضمانات اتفكت. اللحظة اللي عاصم وعماد مستنينها: الشركة كسبت كام بجد بعد الإهلاك والضرايب؟ وكل شريك نصيبه كام؟' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 6, 'امتحان المستوى 6', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 7, 'خريطة السيطرة والمطبات الواقعية', 'فروق الأسعار طبقاً لقانون التعاقدات الحكومية 182 لسنة 2018، الأجور الحكمية في قانون التأمينات 148 لسنة 2019، غرامات التأخير ودفتر أحوال الموقع، شجرة حسابات المقاولات، ومصفوفة مراكز التكلفة.', 'المشروع خلص بسلام، بس عماد قاعد على القهوة بيحكي عن الشركات اللي وقعت: حديد غلي في نص المشروع، تأمينات اتحسبت بأثر رجعي، وغرامة تأخير أكلت الربح كله. هنا هتمسك الأدوات اللي بتحمي المقاول من الإفلاس.' FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'level', 7, 'امتحان المستوى 7', 10, 50, 15 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'cumulative', 3, 'الامتحان التراكمي الأول (المستويات 1 إلى 3)', 20, 50, 40 FROM courses WHERE slug = 'contracting'; INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct, duration_min) SELECT id, 'cumulative', 7, 'الامتحان الشامل (المستويات 1 إلى 7)', 20, 50, 40 FROM courses WHERE slug = 'contracting'; INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'حصة الشريك عاصم في رأس مال شركة الوعد للمقاولات:', '["4,000,000 جنيه","6,000,000 جنيه","5,000,000 جنيه","10,000,000 جنيه"]', 1, 'عاصم جاب 6 مليون من شقا الغربة، وعماد 4 مليون، والإجمالي 10 مليون (الوحدة 1.1).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'حصة الشريك عاصم في رأس مال شركة الوعد للمقاولات:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'نسبة مساهمة الشريك عماد في رأس المال:', '["60%","50%","35%","40%"]', 3, '4,000,000 ÷ 10,000,000 = 40% (الوحدة 1.1).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'نسبة مساهمة الشريك عماد في رأس المال:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'الشكل القانوني اللي اتأسست عليه شركة الوعد:', '["شركة تضامن","شركة توصية بسيطة","منشأة فردية","شركة ذات مسؤولية محدودة"]', 3, 'اتفقوا على ش.ذ.م.م طبقاً لقانون الشركات 159 لسنة 1981 (الوحدة 1.1).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'الشكل القانوني اللي اتأسست عليه شركة الوعد:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'إجمالي مصاريف التأسيس اللي دفعها الشريكان من جيبهم:', '["150,000 جنيه","180,000 جنيه","75,000 جنيه","30,000 جنيه"]', 0, 'توثيق ورسوم غرفة وسجل وقيد في الاتحاد وأتعاب محاماة = 150,000، كل شريك 75,000 (الوحدة 1.1).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'إجمالي مصاريف التأسيس اللي دفعها الشريكان من جيبهم:'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'ليه الشريكان دفعوا مصاريف التأسيس من أموالهم الشخصية؟', '["لأن البنك رفض إيداع رأس المال","لأن المصاريف دي ماتخصش الشركة","لأن حساب الشركة كان متجمد لحد صدور السجل التجاري","لأنهم قرروا يزودوا رأس المال"]', 2, 'الحساب تحت التأسيس فضل متجمد لحد ما السجل التجاري طلع (الوحدة 1.1).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'ليه الشريكان دفعوا مصاريف التأسيس من أموالهم الشخصية؟'); INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1), 'عماد اعتبر الـ 150,000 اللي دفعوها من جيبهم:', '["زيادة في رأس المال","سلفة الشركة مديونة لهم بيها وهترجعها بشيك","تبرع من الشريكين للشركة","مصروف شخصي مالوش علاقة بالشركة"]', 1, 'عماد قال: دي مش زيادة في رأس المال ولا تبرع، دي سلفة وهترجع لنا بشيك (الوحدة 1.1).' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'contracting' AND e.kind = 'level' AND e.after_level = 1) AND body = 'عماد 